<?php

namespace MongoDB\BSON;

use JsonSerializable;
use MongoDB\Driver\Exception\InvalidArgumentException;
use Stringable;

/**
 * <div id="class.mongodb-bson-binary" class="reference"> <h1 class="title">The MongoDB\BSON\Binary class</h1>  <div class="partintro"><p class="verinfo">(mongodb &gt;=1.0.0)</p>  <div class="section" id="mongodb-bson-binary.intro">   <h2 class="title">简介</h2>   <p class="simpara">    BSON type for binary data (i.e. array of bytes). Binary values also have a    subtype, which is used to indicate what kind of data is in the byte array.    Subtypes from zero to 127 are predefined or reserved. Subtypes from 128-255    are user-defined.   </p>  </div>  <div class="section" id="mongodb-bson-binary.synopsis">   <h2 class="title">类摘要</h2>   <div class="classsynopsis">    <span class="ooclass"><strong class="classname"></strong></span>    <div class="classsynopsisinfo">     <span class="modifier">final</span>     <span class="ooclass">      <span class="modifier">class</span> <strong class="classname">MongoDB\BSON\Binary</strong>     </span>     <span class="oointerface"><span class="modifier">implements</span>        <a href="https://php.net/manual/zh/class.mongodb-bson-binaryinterface.php" class="interfacename">MongoDB\BSON\BinaryInterface</a></span><span class="oointerface">,  <a href="https://php.net/manual/zh/class.mongodb-bson-type.php" class="interfacename">MongoDB\BSON\Type</a></span><span class="oointerface">,  <a href="https://php.net/manual/zh/class.jsonserializable.php" class="interfacename">JsonSerializable</a></span><span class="oointerface">,  <a href="https://php.net/manual/zh/class.stringable.php" class="interfacename">Stringable</a></span> {</div>    <div class="classsynopsisinfo classsynopsisinfo_comment">// 常量 </div>    <div class="fieldsynopsis">     <span class="modifier">const</span>     <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span>      <var class="fieldsynopsis_varname"><a href="https://php.net/manual/zh/class.mongodb-bson-binary.php#mongodb-bson-binary.constants.type-generic"><var class="varname">TYPE_GENERIC</var></a></var><span class="initializer"> = 0</span>;</div>    <div class="fieldsynopsis"><span class="modifier">const</span>     <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span>      <var class="fieldsynopsis_varname"><a href="https://php.net/manual/zh/class.mongodb-bson-binary.php#mongodb-bson-binary.constants.type-function"><var class="varname">TYPE_FUNCTION</var></a></var><span class="initializer"> = 1</span>;</div>    <div class="fieldsynopsis"><span class="modifier">const</span>     <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span>      <var class="fieldsynopsis_varname"><a href="https://php.net/manual/zh/class.mongodb-bson-binary.php#mongodb-bson-binary.constants.type-old-binary"><var class="varname">TYPE_OLD_BINARY</var></a></var><span class="initializer"> = 2</span>;</div>    <div class="fieldsynopsis"><span class="modifier">const</span>     <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span>      <var class="fieldsynopsis_varname"><a href="https://php.net/manual/zh/class.mongodb-bson-binary.php#mongodb-bson-binary.constants.type-old-uuid"><var class="varname">TYPE_OLD_UUID</var></a></var><span class="initializer"> = 3</span>;</div>    <div class="fieldsynopsis"><span class="modifier">const</span>     <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span>      <var class="fieldsynopsis_varname"><a href="https://php.net/manual/zh/class.mongodb-bson-binary.php#mongodb-bson-binary.constants.type-uuid"><var class="varname">TYPE_UUID</var></a></var><span class="initializer"> = 4</span>;</div>    <div class="fieldsynopsis"><span class="modifier">const</span>     <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span>      <var class="fieldsynopsis_varname"><a href="https://php.net/manual/zh/class.mongodb-bson-binary.php#mongodb-bson-binary.constants.type-md5"><var class="varname">TYPE_MD5</var></a></var><span class="initializer"> = 5</span>;</div>    <div class="fieldsynopsis"><span class="modifier">const</span>     <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span>      <var class="fieldsynopsis_varname"><a href="https://php.net/manual/zh/class.mongodb-bson-binary.php#mongodb-bson-binary.constants.type-encrypted"><var class="varname">TYPE_ENCRYPTED</var></a></var><span class="initializer"> = 6</span>;</div>    <div class="fieldsynopsis"><span class="modifier">const</span>     <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span>      <var class="fieldsynopsis_varname"><a href="https://php.net/manual/zh/class.mongodb-bson-binary.php#mongodb-bson-binary.constants.type-column"><var class="varname">TYPE_COLUMN</var></a></var><span class="initializer"> = 7</span>;</div>    <div class="fieldsynopsis"><span class="modifier">const</span>     <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span>      <var class="fieldsynopsis_varname"><a href="https://php.net/manual/zh/class.mongodb-bson-binary.php#mongodb-bson-binary.constants.type-sensitive"><var class="varname">TYPE_SENSITIVE</var></a></var><span class="initializer"> = 8</span>;</div>    <div class="fieldsynopsis"><span class="modifier">const</span>     <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span>      <var class="fieldsynopsis_varname"><a href="https://php.net/manual/zh/class.mongodb-bson-binary.php#mongodb-bson-binary.constants.type-vector"><var class="varname">TYPE_VECTOR</var></a></var><span class="initializer"> = 9</span>;</div>    <div class="fieldsynopsis"><span class="modifier">const</span>     <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span>      <var class="fieldsynopsis_varname"><a href="https://php.net/manual/zh/class.mongodb-bson-binary.php#mongodb-bson-binary.constants.type-user-defined"><var class="varname">TYPE_USER_DEFINED</var></a></var><span class="initializer"> = 128</span>;</div>    <div class="classsynopsisinfo classsynopsisinfo_comment">// 方法 </div>    <div class="methodsynopsis dc-description">   <span class="modifier">final</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/mongodb-bson-binary.construct.php" class="methodname" style="color:#CC7832">__construct</a></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span> <span class="parameter" style="color:#3A95FF">\$data</span></span>, <span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span> <span class="parameter" style="color:#3A95FF">\$type</span><span class="initializer"> = MongoDB\BSON\Binary::TYPE_GENERIC</span></span>)</div><div class="methodsynopsis dc-description"><span class="modifier">final</span> <span class="modifier">public</span> <span class="modifier">static</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/mongodb-bson-binary.fromvector.php" class="methodname" style="color:#CC7832">fromVector</a></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.array.php" class="type array" style="color:#EAB766">array</a></span> <span class="parameter" style="color:#3A95FF">\$vector</span></span>, <span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/enum.mongodb-bson-vectortype.php" class="type MongoDB\BSON\VectorType" style="color:#EAB766">MongoDB\BSON\VectorType</a></span> <span class="parameter" style="color:#3A95FF">\$vectorType</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.mongodb-bson-binary.php" class="type MongoDB\BSON\Binary" style="color:#EAB766">MongoDB\BSON\Binary</a></span></div><div class="methodsynopsis dc-description"><span class="modifier">final</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/mongodb-bson-binary.getdata.php" class="methodname" style="color:#CC7832">getData</a></span>(): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span></div><div class="methodsynopsis dc-description"><span class="modifier">final</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/mongodb-bson-binary.gettype.php" class="methodname" style="color:#CC7832">getType</a></span>(): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span></div><div class="methodsynopsis dc-description"><span class="modifier">final</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/mongodb-bson-binary.getvectortype.php" class="methodname" style="color:#CC7832">getVectorType</a></span>(): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/enum.mongodb-bson-vectortype.php" class="type MongoDB\BSON\VectorType" style="color:#EAB766">MongoDB\BSON\VectorType</a></span></div><div class="methodsynopsis dc-description"><span class="modifier">final</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/mongodb-bson-binary.jsonserialize.php" class="methodname" style="color:#CC7832">jsonSerialize</a></span>(): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.mixed.php" class="type mixed" style="color:#EAB766">mixed</a></span></div><div class="methodsynopsis dc-description"><span class="modifier">final</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/mongodb-bson-binary.toarray.php" class="methodname" style="color:#CC7832">toArray</a></span>(): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.array.php" class="type array" style="color:#EAB766">array</a></span></div><div class="methodsynopsis dc-description"><span class="modifier">final</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/mongodb-bson-binary.tostring.php" class="methodname" style="color:#CC7832">__toString</a></span>(): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span></div>   }</div>  </div>  <div class="section" id="mongodb-bson-binary.constants">   <h2 class="title">预定义常量</h2>   <dl>         <dt id="mongodb-bson-binary.constants.type-generic"><strong><span>{@link MongoDB\BSON\Binary::TYPE_GENERIC}</span></strong></dt>     <dd>      <span class="simpara">Generic binary data.</span>     </dd>             <dt id="mongodb-bson-binary.constants.type-function"><strong><span>{@link MongoDB\BSON\Binary::TYPE_FUNCTION}</span></strong></dt>     <dd>      <span class="simpara">Function.</span>     </dd>             <dt id="mongodb-bson-binary.constants.type-old-binary"><strong><span>{@link MongoDB\BSON\Binary::TYPE_OLD_BINARY}</span></strong></dt>     <dd>      <span class="simpara">Generic binary data (deprecated in favor of <strong><span>{@link MongoDB\BSON\Binary::TYPE_GENERIC}</span></strong>).</span>     </dd>             <dt id="mongodb-bson-binary.constants.type-old-uuid"><strong><span>{@link MongoDB\BSON\Binary::TYPE_OLD_UUID}</span></strong></dt>     <dd>      <span class="simpara">       Universally unique identifier (deprecated in favor of       <strong><span>{@link MongoDB\BSON\Binary::TYPE_UUID}</span></strong>). When using this       type, the Binary's data should be 16 bytes in length.      </span>      <span class="simpara">       Historically, other drivers encoded values with this type based on their       language conventions (e.g. varying endianness), which makes it       non-portable. The PHP extension applies no special handling for encoding       or decoding data with this type.      </span>     </dd>             <dt id="mongodb-bson-binary.constants.type-uuid"><strong><span>{@link MongoDB\BSON\Binary::TYPE_UUID}</span></strong></dt>     <dd>      <span class="simpara">       Universally unique identifier. When using this type, the Binary's       data should be 16 bytes in length and encoded according to       <a href="https://datatracker.ietf.org/doc/html/rfc4122" class="link external">»&nbsp;RFC 4122</a>.      </span>     </dd>             <dt id="mongodb-bson-binary.constants.type-md5"><strong><span>{@link MongoDB\BSON\Binary::TYPE_MD5}</span></strong></dt>     <dd>      <span class="simpara">MD5 hash. When using this type, the Binary's data should be 16 bytes in length.</span>     </dd>             <dt id="mongodb-bson-binary.constants.type-encrypted"><strong><span>{@link MongoDB\BSON\Binary::TYPE_ENCRYPTED}</span></strong></dt>     <dd>      <span class="simpara">Encrypted value. This subtype is used for client-side encryption.</span>     </dd>             <dt id="mongodb-bson-binary.constants.type-column"><strong><span>{@link MongoDB\BSON\Binary::TYPE_COLUMN}</span></strong></dt>     <dd>      <span class="simpara">Column data. This subtype is used for time-series collections.</span>     </dd>             <dt id="mongodb-bson-binary.constants.type-sensitive"><strong><span>{@link MongoDB\BSON\Binary::TYPE_SENSITIVE}</span></strong></dt>     <dd>      <span class="simpara">       Sensitive data. This subtype is used for sensitive data that should be       excluded from server-side logging when possible.      </span>     </dd>             <dt id="mongodb-bson-binary.constants.type-vector"><strong><span>{@link MongoDB\BSON\Binary::TYPE_VECTOR}</span></strong></dt>     <dd>      <span class="simpara">       Vector data. This subtype is used to efficiently store vector data for       use with MongoDB's vector search.      </span>     </dd>             <dt id="mongodb-bson-binary.constants.type-user-defined"><strong><span>{@link MongoDB\BSON\Binary::TYPE_USER_DEFINED}</span></strong></dt>     <dd>      <span class="simpara">       User-defined type. While types between 0 and 127 are predefined or       reserved, types between 128 and 255 are user-defined and may be used for       anything.      </span>     </dd>       </dl>  </div>  <div class="section">   <h2 class="title">更新日志</h2>   <table class="doctable informaltable">         <thead>      <tr>       <th>版本</th>       <th>说明</th>      </tr>     </thead>     <tbody class="tbody">      <tr>       <td>PECL mongodb 2.2.0</td>       <td>        Added <strong><span>{@link MongoDB\BSON\Binary::TYPE_VECTOR}</span></strong>, as well as the        <span class="methodname" style="color:#CC7832">{@link MongoDB\BSON\Binary::fromVector()}</span>,        <span class="methodname" style="color:#CC7832">{@link MongoDB\BSON\Binary::getVectorType()}</span>, and        <span class="methodname" style="color:#CC7832">{@link MongoDB\BSON\Binary::toArray()}</span> functions.       </td>      </tr>             <tr>        <td>PECL mongodb 2.0.0</td>        <td>         <span class="simpara">          此类不再实现 <span class="interfacename"><a href="https://php.net/manual/zh/class.serializable.php" class="interfacename">Serializable</a></span> 接口。         </span>        </td>       </tr>      <tr>       <td>PECL mongodb 1.17.0</td>       <td>        Added <strong><span>{@link MongoDB\BSON\Binary::TYPE_SENSITIVE}</span></strong>.       </td>      </tr>      <tr>       <td>PECL mongodb 1.12.0</td>       <td>        <span class="simpara">         Implements <span class="interfacename"><a href="https://php.net/manual/zh/class.stringable.php" class="interfacename">Stringable</a></span> for PHP 8.0+.        </span>        <span class="simpara">         Added <strong><span>{@link MongoDB\BSON\Binary::TYPE_COLUMN}</span></strong>.        </span>       </td>      </tr>      <tr>       <td>PECL mongodb 1.7.0</td>       <td>        Added <strong><span>{@link MongoDB\BSON\Binary::TYPE_ENCRYPTED}</span></strong>.       </td>      </tr>      <tr>       <td>PECL mongodb 1.3.0</td>       <td>        Implements <span class="interfacename"><a href="https://php.net/manual/zh/class.mongodb-bson-binaryinterface.php" class="interfacename">MongoDB\BSON\BinaryInterface</a></span>.       </td>      </tr>      <tr>       <td>PECL mongodb 1.2.0</td>       <td>        Implements <span class="interfacename"><a href="https://php.net/manual/zh/class.serializable.php" class="interfacename">Serializable</a></span> and        <span class="interfacename"><a href="https://php.net/manual/zh/class.jsonserializable.php" class="interfacename">JsonSerializable</a></span>.       </td>      </tr>     </tbody>       </table>  </div> </div> <h2>目录</h2><ul class="chunklist chunklist_reference"><li>{@link MongoDB\BSON\Binary::__construct} — Construct a new Binary</li><li>{@link MongoDB\BSON\Binary::fromVector} — Creates a new binary with subtype MongoDB\BSON\Binary::SUBTYPE_VECTOR from the given array and vector type</li><li>{@link MongoDB\BSON\Binary::getData} — Returns the Binary's data</li><li>{@link MongoDB\BSON\Binary::getType} — Returns the Binary's type</li><li>{@link MongoDB\BSON\Binary::getVectorType} — Returns the data type for a Binary with the vector subtype</li><li>{@link MongoDB\BSON\Binary::jsonSerialize} — Returns a representation that can be converted to JSON</li><li>{@link MongoDB\BSON\Binary::toArray} — Returns the vector as an array for a Binary with subtype MongoDB\BSON\Binary::SUBTYPE_VECTOR</li><li>{@link MongoDB\BSON\Binary::__toString} — Returns the Binary's data</li></ul></div>
 * 
 * Class Binary
 * @link https://php.net/manual/zh/class.mongodb-bson-binary.php
 */
final class Binary implements Type, BinaryInterface, JsonSerializable, Stringable
{
    public const TYPE_GENERIC = 0, TYPE_FUNCTION = 1;
    public const TYPE_OLD_BINARY = 2;
    public const TYPE_OLD_UUID = 3;
    public const TYPE_UUID = 4;
    public const TYPE_MD5 = 5;

    /**
     * @since 1.7.0
     */
    public const TYPE_ENCRYPTED = 6;

    /**
     * @since 1.12.0
     */
    public const TYPE_COLUMN = 7;

    /**
     * @since 1.17.0
     */
    public const TYPE_SENSITIVE = 8;

    /**
     * @since 2.2.0
     */
    public const TYPE_VECTOR = 9;
    public const TYPE_USER_DEFINED = 128;

    /**
 * <div id="mongodb-bson-binary.construct" class="refentry"> <div class="refnamediv">  <h1 class="refname">MongoDB\BSON\Binary::__construct</h1>  <p class="verinfo">(mongodb &gt;=1.0.0)</p><p class="refpurpose"><span class="refname">MongoDB\BSON\Binary::__construct</span> — <span class="dc-title">Construct a new Binary</span></p> </div> <div class="refsect1 description" id="refsect1-mongodb-bson-binary.construct-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">final</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>MongoDB\BSON\Binary::__construct</strong></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span> <span class="parameter" style="color:#3A95FF">\$data</span></span>, <span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span> <span class="parameter" style="color:#3A95FF">\$type</span><span class="initializer"> = MongoDB\BSON\Binary::TYPE_GENERIC</span></span>)</div> </div> <div class="refsect1 parameters" id="refsect1-mongodb-bson-binary.construct-parameters">  <h3 class="title">参数</h3>  <dl>       <dt><span class="parameter" style="color:#3A95FF">data</span> (<span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span>)</dt>    <dd>     <span class="simpara">      Binary data.     </span>    </dd>          <dt><span class="parameter" style="color:#3A95FF">type</span> (<span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span>)</dt>    <dd>     <span class="simpara">      Unsigned 8-bit integer denoting the data's type. Defaults to <strong><span>{@link MongoDB\BSON\Binary::TYPE_GENERIC}</span></strong> if not specified.     </span>    </dd>     </dl> </div> <div class="refsect1 errors" id="refsect1-mongodb-bson-binary.construct-errors">  <h3 class="title">错误／异常</h3>  <ul class="simplelist">   <li>Throws <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-exception-invalidargumentexception.php" class="classname">MongoDB\Driver\Exception\InvalidArgumentException</a></span> on argument parsing errors.</li>   <li>Throws <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-exception-invalidargumentexception.php" class="classname">MongoDB\Driver\Exception\InvalidArgumentException</a></span> if <span class="parameter" style="color:#3A95FF">type</span> is not an unsigned 8-bit integer.</li>   <li>Throws <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-exception-invalidargumentexception.php" class="classname">MongoDB\Driver\Exception\InvalidArgumentException</a></span> if <span class="parameter" style="color:#3A95FF">type</span> is <strong><span>{@link MongoDB\BSON\Binary::TYPE_UUID}</span></strong> or <strong><span>{@link MongoDB\BSON\Binary::TYPE_OLD_UUID}</span></strong> and <span class="parameter" style="color:#3A95FF">data</span> is not exactly 16 bytes in length.</li>  </ul> </div> <div class="refsect1 changelog" id="refsect1-mongodb-bson-binary.construct-changelog">  <h3 class="title">更新日志</h3>  <table class="doctable informaltable">       <thead>     <tr>      <th>版本</th>      <th>说明</th>     </tr>    </thead>    <tbody class="tbody">     <tr>      <td>PECL mongodb 1.15.0</td>      <td>       <span class="simpara">        The <span class="parameter" style="color:#3A95FF">type</span> parameter defaults to        <strong><span>{@link MongoDB\BSON\Binary::TYPE_GENERIC}</span></strong> if not specified.       </span>      </td>     </tr>     <tr>      <td>PECL mongodb 1.3.0</td>      <td>       <span class="simpara">        <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-exception-invalidargumentexception.php" class="classname">MongoDB\Driver\Exception\InvalidArgumentException</a></span>        is thrown if <span class="parameter" style="color:#3A95FF">type</span> is        <strong><span>{@link MongoDB\BSON\Binary::TYPE_UUID}</span></strong> or        <strong><span>{@link MongoDB\BSON\Binary::TYPE_OLD_UUID}</span></strong> and        <span class="parameter" style="color:#3A95FF">data</span> is not exactly 16 bytes in length.       </span>      </td>     </tr>     <tr>      <td>PECL mongodb 1.1.3</td>      <td>       <span class="simpara">        <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-exception-invalidargumentexception.php" class="classname">MongoDB\Driver\Exception\InvalidArgumentException</a></span>        is thrown if <span class="parameter" style="color:#3A95FF">type</span> is not an unsigned 8-bit        integer.       </span>      </td>     </tr>    </tbody>     </table> </div> <div class="refsect1 examples" id="refsect1-mongodb-bson-binary.construct-examples">  <h3 class="title">示例</h3>  <div class="example" id="example-1">   <p><strong>示例 #1 <span class="function"><strong style="color:#CC7832">MongoDB\BSON\Binary::__construct()</strong></span> example</strong></p>   <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br><br>\$binary </span><span style="color: #007700">= new </span><span style="color: #9876AA">MongoDB\BSON\Binary</span><span style="color: #007700">(</span><span style="color: #DD0000">'foo'</span><span style="color: #007700">, </span><span style="color: #9876AA">MongoDB\BSON\Binary</span><span style="color: #007700">::</span><span style="color: #9876AA">TYPE_GENERIC</span><span style="color: #007700">);<br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">\$binary</span><span style="color: #007700">);<br><br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>   <div class="example-contents"><p>以上示例会输出：</p></div>   <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><div class="examplescode"><blockquote style="border:1px gray solid;">object(MongoDB\BSON\Binary)#1&nbsp;(2)&nbsp;{<br>&nbsp;&nbsp;["data"]=&gt;<br>&nbsp;&nbsp;string(3)&nbsp;"foo"<br>&nbsp;&nbsp;["type"]=&gt;<br>&nbsp;&nbsp;int(0)<br>}</blockquote></div>   </div>  </div> </div> <div class="refsect1 seealso" id="refsect1-mongodb-bson-binary.construct-seealso">  <h3 class="title">参见</h3>  <ul class="simplelist">   <li><a href="https://www.mongodb.com/docs/manual/reference/bson-types/" class="link external">»&nbsp;BSON Types</a></li>  </ul> </div></div>
 * 
     * Binary constructor.
     * @link https://php.net/manual/zh/mongodb-bson-binary.construct.php
     */
    final public function __construct(string $data, int $type = Binary::TYPE_GENERIC) {}

    /**
 * <div id="mongodb-bson-binary.fromvector" class="refentry"> <div class="refnamediv">  <h1 class="refname">MongoDB\BSON\Binary::fromVector</h1>  <p class="verinfo">(mongodb &gt;=2.2.0)</p><p class="refpurpose"><span class="refname">MongoDB\BSON\Binary::fromVector</span> — <span class="dc-title">Creates a new binary with subtype <strong><span>MongoDB\BSON\Binary::SUBTYPE_VECTOR</span></strong> from the given array and vector type</span></p> </div> <div class="refsect1 description" id="refsect1-mongodb-bson-binary.fromvector-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">final</span> <span class="modifier">public</span> <span class="modifier">static</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>MongoDB\BSON\Binary::fromVector</strong></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.array.php" class="type array" style="color:#EAB766">array</a></span> <span class="parameter" style="color:#3A95FF">\$vector</span></span>, <span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/enum.mongodb-bson-vectortype.php" class="type MongoDB\BSON\VectorType" style="color:#EAB766">MongoDB\BSON\VectorType</a></span> <span class="parameter" style="color:#3A95FF">\$vectorType</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.mongodb-bson-binary.php" class="type MongoDB\BSON\Binary" style="color:#EAB766">MongoDB\BSON\Binary</a></span></div> </div> <div class="refsect1 parameters" id="refsect1-mongodb-bson-binary.fromvector-parameters">  <h3 class="title">参数</h3>  <dl>       <dt><span class="parameter" style="color:#3A95FF">vector</span> (<span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.array.php" class="type array" style="color:#EAB766">array</a></span>)</dt>    <dd>     <p class="para">      An array of values representing the vector data. The type of each value must match the type indicated by the <span class="parameter" style="color:#3A95FF">vectorType</span> parameter:      </p><ul class="itemizedlist">       <li class="listitem"><span class="simpara">for <strong><span>MongoDB\BSON\VectorType::Float32</span></strong>, each value must be a <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.float.php" class="type float" style="color:#EAB766">float</a></span></span></li>       <li class="listitem"><span class="simpara">for <strong><span>MongoDB\BSON\VectorType::Int8</span></strong>, each value must be an 8-bit <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span>, i.e. from <span class="literal">-127</span> to <span class="literal">128</span></span></li>       <li class="listitem"><span class="simpara">for <strong><span>MongoDB\BSON\VectorType::PackedBit</span></strong>, each value must be a <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.boolean.php" class="type bool" style="color:#EAB766">bool</a></span> or 1-bit <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span>, i.e. <span class="literal">0</span> or <span class="literal">1</span></span></li>      </ul>         </dd>          <dt><span class="parameter" style="color:#3A95FF">vectorType</span> (<span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/enum.mongodb-bson-vectortype.php" class="type MongoDB\BSON\VectorType" style="color:#EAB766">MongoDB\BSON\VectorType</a></span>)</dt>    <dd>     <span class="simpara">      The vector data type.     </span>    </dd>     </dl> </div> <div class="refsect1 returnvalues" id="refsect1-mongodb-bson-binary.fromvector-returnvalues">  <h3 class="title">返回值</h3>  <p class="simpara">   Returns a new Binary with subtype <strong><span>MongoDB\BSON\Binary::SUBTYPE_VECTOR</span></strong>.  </p> </div> <div class="refsect1 errors" id="refsect1-mongodb-bson-binary.fromvector-errors">  <h3 class="title">错误／异常</h3>  <ul class="simplelist">   <li>Throws <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-exception-invalidargumentexception.php" class="classname">MongoDB\Driver\Exception\InvalidArgumentException</a></span> on argument parsing errors.</li>  </ul> </div> <div class="refsect1 seealso" id="refsect1-mongodb-bson-binary.fromvector-seealso">  <h3 class="title">参见</h3>  <ul class="simplelist">   <li><span class="methodname" style="color:#CC7832">{@link MongoDB\BSON\Binary::toArray()} - Returns the vector as an array for a Binary with subtype MongoDB\BSON\Binary::SUBTYPE_VECTOR</span></li>   <li><span class="methodname" style="color:#CC7832">{@link MongoDB\BSON\Binary::getVectorType()} - Returns the data type for a Binary with the vector subtype</span></li>   <li><span class="enumname"><a href="https://php.net/manual/zh/enum.mongodb-bson-vectortype.php" class="enumname">MongoDB\BSON\VectorType</a></span></li>   <li><a href="https://www.mongodb.com/docs/manual/reference/bson-types/" class="link external">»&nbsp;BSON Types</a></li>  </ul> </div></div>
 * 
     * Create a binary from a given vector and vector type.
     * @link https://php.net/manual/zh/mongodb-bson-binary.fromvector.php
     */
    final public static function fromVector(array $vector, VectorType $vectorType): self {}

