ockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br><br>\$binary </span><span style="color: #007700">= new </span><span style="color: #9876AA">MongoDB\BSON\Binary</span><span style="color: #007700">(</span><span style="color: #DD0000">'foo'</span><span style="color: #007700">, </span><span style="color: #9876AA">MongoDB\BSON\Binary</span><span style="color: #007700">::</span><span style="color: #9876AA">TYPE_GENERIC</span><span style="color: #007700">);<br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">\$binary</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">getType</span><span style="color: #007700">());<br><br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>   <div class="example-contents"><p>以上示例会输出：</p></div>   <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><div class="examplescode"><blockquote style="border:1px gray solid;">int(0)</blockquote></div>   </div>  </div> </div> <div class="refsect1 seealso" id="refsect1-mongodb-bson-binary.gettype-seealso">  <h3 class="title">参见</h3>  <ul class="simplelist">   <li><a href="https://www.mongodb.com/docs/manual/reference/bson-types/" class="link external">»&nbsp;BSON Types</a></li>  </ul> </div></div>
